const NAME = pm.variables.replaceIn("{{$randomFirstName}} {{$randomLastName}}");
const USERNAME = NAME.toLowerCase().replace(/ /g, '_');
const EMAIL = `${USERNAME}@test.de`;
pm.variables.set("USERNAME", USERNAME);
pm.variables.set("EMAIL", EMAIL);

pm.test("Status code is 201", () => pm.response.to.have.status(201));
const body = pm.response.json();
pm.test("Response has token and user_id", () => {
    pm.expect(body).to.have.property('token');
    pm.expect(body).to.have.property('user_id');
});
if (pm.response.code === 201) {
    pm.environment.set("BusinessToken", body.token);
    pm.environment.set("businessUserId", body.user_id);
    pm.environment.set("businessUsername", body.username);
}

